@app.post("/command/<operation>")
def command(operation):
    actor=service.principal(session.get("user_id"))
    if request.headers.get("Origin") and request.headers["Origin"]!=request.host_url.rstrip("/"):
        raise DomainError("origin_not_allowed")
    if operation!="login" and not secrets.compare_digest(request.form.get("csrf",""),session.get("csrf","missing")):
        raise DomainError("csrf_required")
    try:
        if operation=="login":
            session.clear()
            user=service.sign_in(request.form.get("username",""),request.form.get("password",""))
            session.update(user_id=user["id"],csrf=secrets.token_hex(24))
        elif operation=="logout":
            service.sign_out(actor)
            session.clear()
        elif operation=="upload":
            upload=request.files.get("file")
            if upload is None:
                raise DomainError("file_required",400)
            service.upload_file(actor,upload.filename or "",upload.read())
            flash("文件已上传，等待管理员审核。")
        elif operation=="review":
            service.review_file(actor,request.form.get("file_id",""),request.form.get("decision",""),request.form.get("reason",""))
            flash("审核结果等待消息投递，送达后生效。")
        elif operation=="share":
            service.share_file(actor,request.form.get("file_id",""),request.form.get("recipient_id",""))
            flash("共享消息等待投递，送达后同事才能访问。")
        else:
            raise DomainError("route_not_found",404)
    except DomainError as error:
        flash({"invalid_credentials":"账号或密码不正确","review_not_allowed":"不能审核自己的文件；需要另一位管理员处理。",
            "share_not_allowed":"只有上传者能共享审核已生效的文件。","invalid_review":"驳回时请填写原因。",
            "share_already_exists":"已为这位同事创建共享。","authentication_required":"请先登录。"}.get(error.code,error.code))
    return redirect("/",code=303)

